`timescale 1ns/1ps
// Vivado ILA/VIO IP generated by scripts/create_ila_project.tcl.
// The synthetic benchmark never drives sensor requests or sensor bus pins.
module arbiter_debug(input wire clk,rst,
    input wire [1:0] live_req,live_grant,live_done,initialized,fault,
    input wire [8:0] live_eff0,live_eff1, output wire live_aging_enable);
    wire test_start,test_aging,select_test;
    wire [1:0] test_req,test_grant,test_done;
    wire [8:0] test_eff0,test_eff1;
    wire active,finished,start_event,aging_latched;
    wire [31:0] lt,lw0,lw1,lm0,lm1,lg0,lg1;
    wire [31:0] tt,tw0,tw1,tm0,tm1,tg0,tg1;
    arbiter_metrics live_metrics(.clk(clk),.rst(rst),.req(live_req),.grant(live_grant),
        .timestamp(lt),.wait0(lw0),.wait1(lw1),.max_wait0(lm0),.max_wait1(lm1),.grants0(lg0),.grants1(lg1));
    arbiter_stress_demo benchmark(.clk(clk),.rst(rst),.start(test_start),.aging_enable(test_aging),
        .req(test_req),.grant(test_grant),.done(test_done),.eff0(test_eff0),.eff1(test_eff1),
        .active(active),.finished(finished),.start_event(start_event),.aging_latched(aging_latched),
        .timestamp(tt),.wait0(tw0),.wait1(tw1),.max_wait0(tm0),.max_wait1(tm1),.grants0(tg0),.grants1(tg1));
    vio_arb control(.clk(clk),.probe_out0(test_start),.probe_out1(test_aging),
        .probe_out2(select_test),.probe_out3(live_aging_enable),
        .probe_in0(active),.probe_in1(finished),.probe_in2(select_test?tg0:lg0),.probe_in3(select_test?tg1:lg1),
        .probe_in4(select_test?tm0:lm0),.probe_in5(select_test?tm1:lm1));
    wire [7:0] context_flags={initialized,fault,finished,active,
        (select_test?aging_latched:live_aging_enable),select_test};
    ila_arb capture(.clk(clk),.probe0(context_flags),
        .probe1(select_test?test_req:live_req),.probe2(select_test?test_grant:live_grant),
        .probe3(select_test?test_done:live_done),.probe4(select_test?test_eff0:live_eff0),
        .probe5(select_test?test_eff1:live_eff1),.probe6(select_test?tt:lt),
        .probe7(select_test?tw0:lw0),.probe8(select_test?tw1:lw1),
        .probe9(start_event));
endmodule
